beforeExample:
import org.eclipse.e4.ui.model.menu.MDirectMenuItem;
import org.eclipse.e4.ui.model.menu.MMenuFactory;

class MyClass {
    void setupMenu() {
        MDirectMenuItem item = MMenuFactory.INSTANCE.createDirectMenuItem();
        String PLUGIN_ID = "org.eclipse.debug.ui.launchview";
        item.setIconURI("platform:/plugin/" + PLUGIN_ID + "/icons/remove_exc.png");
    }
}

